-- Gerado por scripts/gerar-seed.cjs a partir de public/js/dados.js. Não edite à mão.
-- Pode ser executado várias vezes: atualiza os produtos e não duplica categorias nem marcas.

SELECT v.nome FROM (VALUES ('consoles'), ('jogos'), ('perifericos')) AS v (nome)
WHERE NOT EXISTS (SELECT 1 FROM categoria c WHERE lower(c.nome) = lower(v.nome));

SELECT v.nome FROM (VALUES ('Sony'), ('Microsoft'), ('Nintendo'), ('Unknown Worlds'), ('Team Cherry'), ('CD Projekt Red'), ('Rockstar Games'), ('NetherRealm Studios'), ('Warner Bros. Games'), ('Mojang Studios'), ('Bethesda'), ('Activision'), ('Electronic Arts'), ('Hello Games'), ('Redragon'), ('JBL'), ('KZ'), ('QCY'), ('Corsair')) AS v (nome)
WHERE NOT EXISTS (SELECT 1 FROM marca m WHERE lower(m.nome) = lower(v.nome));

ON CONFLICT (id_produto) DO UPDATE SET
  slug = EXCLUDED.slug, nome = EXCLUDED.nome, id_categoria = EXCLUDED.id_categoria, id_marca = EXCLUDED.id_marca,
  plataformas = EXCLUDED.plataformas, preco = EXCLUDED.preco, preco_antigo = EXCLUDED.preco_antigo,
  etiqueta = EXCLUDED.etiqueta, imagem = EXCLUDED.imagem, tipo = EXCLUDED.tipo, ativo = EXCLUDED.ativo;
-- (a coluna estoque fica de fora do UPDATE de propósito)

-- Mantém o contador automático alinhado com os ids inseridos (caso a coluna seja serial).
SELECT setval(pg_get_serial_sequence('produto', 'id_produto'), (SELECT max(id_produto) FROM produto))
WHERE pg_get_serial_sequence('produto', 'id_produto') IS NOT NULL;
